//! C++ compatibility shims.
//!
//! These modules exist purely to reproduce libstdc++ / glibc observable behaviour
//! that Rust's standard library spells differently. Nothing in here is "better"
//! than the Rust idiom it replaces -- it is here because the reference binary
//! does it this way and the port is graded on byte-for-byte parity.
//!
//! * [`stoi`]  -- `std::stoi` parsing semantics (C-locale `strtol`) and the
//!   uncaught-exception termination path (`std::terminate` -> `SIGABRT`).
//! * [`fixed`] -- `std::ostream << std::fixed << std::setprecision(n)` formatting.

// The modules below are a small library surface: `main` exercises the happy path,
// while the accessors, the `&str` entry point and the non-finite branches are
// covered by the `#[cfg(test)]` suites. Without this, a *binary* crate reports
// everything `main` does not transitively call as dead code.
#![allow(dead_code)]

pub mod fixed;
pub mod stoi;

//! `std::ostream << std::fixed << std::setprecision(n) << value` in Rust.
//!
//! # Why this module exists
//!
//! In the reference binary both `ProgressDisplay::display()` and
//! `Percentage::str()` build a `std::ostringstream`, set the `fixed` float field
//! and a precision, then insert a `double`. The manipulators were inlined by GCC
//! into raw `ios_base` field writes:
//!
//! ```text
//! mov  DWORD PTR [rdx+0x8], 0x1      ; _M_precision = 1        (setprecision)
//! mov  eax, DWORD PTR [rdx+0x18]
//! and  eax, 0xfffffefb               ; clear floatfield (~(_S_fixed|_S_scientific))
//! or   eax, 0x4                      ; set _S_fixed            (std::fixed)
//! mov  DWORD PTR [rdx+0x18], eax
//! ```
//!
//! That is exactly `setf(ios_base::fixed, ios_base::floatfield)`. libstdc++ then
//! routes `_M_insert<double>` through `num_put` -> `__convert_from_v` ->
//! glibc `snprintf("%.*f")`.
//!
//! # Parity with Rust's `{:.N}`
//!
//! glibc's `%.*f` and Rust's `{:.N}` both round **half-to-even on the exact
//! binary value** of the operand, and both expand huge magnitudes in full rather
//! than falling back to exponential notation. An exhaustive comparison over all
//! 2^32 `f32` bit patterns at precisions 1..=3 found **zero** differences for
//! finite values and for +/-inf. So no custom rounding, no manual digit
//! expansion, and no `-0.0` special case are required: `format!("{:.*}")` is a
//! drop-in.
//!
//! The single divergence in the whole domain is the spelling of NaN, handled by
//! [`format_fixed`] below.

/// Formats `value` the way `std::ostream` would under `std::fixed` and
/// `std::setprecision(precision)`.
///
/// Callers pass an `f64` because that is what the reference binary hands to the
/// stream: both call sites compute in `f32` and then widen with a single
/// `cvtss2sd` before the insertion. Widening is provably lossless for formatting
/// -- `{:.N}` on an `f32` and on that same `f32 as f64` agree for all 2^32
/// patterns -- but taking `f64` here keeps the port's data flow shaped like the
/// disassembly.
///
/// # Non-finite values
///
/// * **Infinity** -- C++ prints `inf` / `-inf` and so does Rust. Nothing to do.
/// * **NaN** -- C++ prints `nan` / `-nan` (the sign bit is honoured, and glibc
///   emits it lowercase), whereas Rust prints `NaN` and drops the sign. This is
///   the *only* place the two formatters disagree, so it is patched here.
///
/// ## Is the NaN branch reachable?
///
/// **No, not from this program** -- it is defensive only:
///
/// * `ProgressDisplay::display()` divides by `total`, which `main` hard-codes to
///   `200`, so there is no `0.0 / 0.0`. Sweeping all 2^32 values of `current`
///   through the real formula yields only finite results, spanning
///   `[-1073741824.0, 1073741824.0]` -- no NaN, no infinity, not even `-0.0`.
/// * The three `Percentage` values in `main` are the literals `0.15`, `0.35` and
///   `0.65`.
///
/// The branch is kept because [`Percentage::new`](crate::indicators::Percentage::new)
/// is public and would otherwise silently diverge from C++ for a caller that
/// passes `f32::NAN`.
pub fn format_fixed(value: f64, precision: usize) -> String {
    if value.is_nan() {
        // glibc prints the sign bit of a NaN; Rust's `{}`/`{:.N}` prints a bare
        // "NaN". Note `is_sign_negative` inspects the sign bit, which is exactly
        // what printf does -- do not "simplify" this to `value < 0.0`, which is
        // always false for NaN.
        return if value.is_sign_negative() {
            String::from("-nan")
        } else {
            String::from("nan")
        };
    }

    // Finite and infinite values: byte-identical to glibc's "%.*f".
    format!("{:.*}", precision, value)
}

#[cfg(test)]
mod tests {
    use super::format_fixed;

    #[test]
    fn matches_the_five_official_examples() {
        // The percentages printed by the reference binary for the documented runs.
        assert_eq!(format_fixed(0.0, 1), "0.0");
        assert_eq!(format_fixed(12.5, 1), "12.5");
        assert_eq!(format_fixed(25.0, 1), "25.0");
        assert_eq!(format_fixed(50.0, 1), "50.0");
        assert_eq!(format_fixed(75.0, 1), "75.0");
        assert_eq!(format_fixed(87.5, 1), "87.5");
    }

    #[test]
    fn precision_controls_trailing_zeros_like_setprecision() {
        assert_eq!(format_fixed(15.0, 1), "15.0");
        assert_eq!(format_fixed(35.0, 2), "35.00");
        assert_eq!(format_fixed(65.0, 3), "65.000");
        // Precision 0 drops the decimal point entirely, as `std::fixed` does.
        assert_eq!(format_fixed(65.0, 0), "65");
    }

    #[test]
    fn rounds_half_to_even_on_the_exact_binary_value() {
        // Ties are resolved to even, matching glibc rather than "round half up".
        assert_eq!(format_fixed(0.25, 1), "0.2");
        assert_eq!(format_fixed(0.75, 1), "0.8");
        assert_eq!(format_fixed(0.125, 2), "0.12");
        assert_eq!(format_fixed(0.375, 2), "0.38");
    }

    #[test]
    fn huge_magnitudes_expand_in_full_never_exponential() {
        // `std::fixed` never switches to scientific notation, and neither does Rust.
        assert_eq!(format_fixed(1073741824.0, 1), "1073741824.0");
        assert_eq!(format_fixed(-1073741824.0, 1), "-1073741824.0");
        assert!(!format_fixed(1e30f32 as f64, 1).contains('e'));
        assert_eq!(
            format_fixed(1e30f32 as f64, 1),
            "1000000015047466219876688855040.0"
        );
    }

    #[test]
    fn negative_zero_keeps_its_sign_like_cpp() {
        assert_eq!(format_fixed(-0.0, 1), "-0.0");
        assert_eq!(format_fixed(0.0, 1), "0.0");
    }

    #[test]
    fn infinity_needs_no_shim() {
        assert_eq!(format_fixed(f64::INFINITY, 1), "inf");
        assert_eq!(format_fixed(f64::NEG_INFINITY, 3), "-inf");
    }

    #[test]
    fn nan_is_spelled_the_cpp_way() {
        // Rust alone would say "NaN" for both of these.
        assert_eq!(format_fixed(f64::NAN, 1), "nan");
        assert_eq!(format_fixed(-f64::NAN, 1), "-nan");
        assert_eq!(format_fixed(f64::NAN, 7), "nan");
    }

    #[test]
    fn widening_f32_to_f64_does_not_change_the_rendering() {
        // Justifies the `f64` parameter type: the cvtss2sd in the binary is inert.
        for bits in [0x3e19_9999u32, 0x4170_0001, 0x4a7f_ffff, 0xcf00_0000] {
            let v = f32::from_bits(bits);
            for p in 0..=6 {
                assert_eq!(format_fixed(v as f64, p), format!("{:.*}", p, v));
            }
        }
    }
}

//! `std::stoi` semantics, and the termination path taken when it throws.
//!
//! `std::stoi(s)` is specified as a `strtol(s.c_str(), &end, 10)` call plus two
//! checks, and libstdc++ implements exactly that:
//!
//! * no characters consumed  -> `throw std::invalid_argument("stoi")`
//! * `errno == ERANGE`, or the `long` result does not fit in `int`
//!   -> `throw std::out_of_range("stoi")`
//!
//! The reference binary calls `strtol` directly (visible at `0x402422`) and
//! range-checks with the usual `lea rax, [result + 0x80000000]; cmp` idiom.
//! `main` never catches, so a throw unwinds out of `main` into `std::terminate`.
//!
//! Everything here is C-locale: the program never calls `setlocale`, so the set
//! of accepted "space" bytes is fixed and does **not** grow under
//! `LC_ALL=en_US.UTF-8`.

use std::io::Write;

/// Which C++ exception `std::stoi` threw.
///
/// Both variants carry the same `what()` string -- the literal `"stoi"` at
/// `0x403019` in the reference binary is shared by the two throw sites -- so the
/// variant only selects the exception *type name* printed by the terminate
/// handler.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum StoiError {
    /// No digits were consumed: `std::invalid_argument`.
    Invalid,
    /// Digits were consumed but the value does not fit in `int`: `std::out_of_range`.
    OutOfRange,
}

impl StoiError {
    /// The fully-qualified C++ type name, as the GCC terminate handler prints it.
    ///
    /// libstdc++ demangles the exception's `type_info` name, which is why the
    /// message says `std::invalid_argument` and not `St16invalid_argument`.
    pub fn cxx_type_name(self) -> &'static str {
        match self {
            StoiError::Invalid => "std::invalid_argument",
            StoiError::OutOfRange => "std::out_of_range",
        }
    }

    /// The exception's `what()` payload. `std::stoi` passes the literal `"stoi"`
    /// for *both* failure kinds.
    pub fn what(self) -> &'static str {
        "stoi"
    }
}

/// The six bytes `isspace` accepts in the C locale, which is what `strtol` skips.
///
/// Deliberately byte-based, not `char::is_whitespace`: Unicode spaces such as
/// U+00A0 (NBSP) or U+3000 (ideographic space) are **not** skipped by `strtol`
/// and must fall through to `invalid_argument`.
#[inline]
fn is_c_space(b: u8) -> bool {
    b == b' ' || (0x09..=0x0d).contains(&b)
}

/// `std::stoi` over a UTF-8 string.
///
/// Convenience wrapper matching the common case; the parse itself is byte-wise,
/// so this just forwards to [`c_stoi_bytes`]. Command-line arguments must use
/// [`c_stoi_bytes`] instead, because argv is not guaranteed to be UTF-8 and the
/// C++ program accepts (and rejects with `invalid_argument`) arbitrary bytes.
pub fn c_stoi(s: &str) -> Result<i32, StoiError> {
    c_stoi_bytes(s.as_bytes())
}

/// `std::stoi` over raw bytes -- the faithful entry point.
///
/// Grammar, in order: optional run of C-locale spaces, one optional `+`/`-`, then
/// one or more ASCII decimal digits. Parsing stops at the first byte that is not
/// a digit; trailing junk is simply ignored (`"12abc"` -> `12`), because
/// `std::stoi` only inspects `end` to see whether it advanced at all.
///
/// # Quirks preserved on purpose
///
/// * **Trailing junk is not an error.** Do not "fix" this to reject `"12abc"`.
/// * **No whitespace may separate the sign from the digits.** `"  +  7"` is
///   `invalid_argument`, even though `"  +7"` is `7`.
/// * **Base is always 10.** `"0x10"` is `0` (parse stops at `x`), `"010"` is
///   `10`, not octal.
/// * **Leading zeros are free and unbounded.** Ten thousand `0`s followed by
///   `42` is `42`, so a "more than 10 digits means overflow" shortcut is wrong.
/// * **Overflow is decided over the whole digit run**, before the trailing junk
///   is discarded, so `"2147483648abc"` is `out_of_range` rather than a
///   successful parse of a truncated prefix.
/// * **`-2147483648` is accepted.** `strtol` accumulates negatively, so
///   `i32::MIN` needs no special case -- and the accumulator here does the same.
pub fn c_stoi_bytes(s: &[u8]) -> Result<i32, StoiError> {
    let mut i = 0usize;

    while i < s.len() && is_c_space(s[i]) {
        i += 1;
    }

    let negative = if i < s.len() && (s[i] == b'+' || s[i] == b'-') {
        let neg = s[i] == b'-';
        i += 1;
        neg
    } else {
        false
    };

    let digits_start = i;

    // Accumulate negatively, exactly as strtol does, so that i32::MIN is
    // representable without a magnitude special case.
    let mut acc: i64 = 0;
    let mut overflowed = false;
    while i < s.len() && s[i].is_ascii_digit() {
        if !overflowed {
            acc = acc * 10 - i64::from(s[i] - b'0');
            if acc < i64::from(i32::MIN) {
                // Latch and stop accumulating, but keep scanning: the digit run
                // may be arbitrarily long and `acc` must not itself overflow.
                // Worst pre-latch value is about -2.1e10, far inside i64.
                overflowed = true;
            }
        }
        i += 1;
    }

    if i == digits_start {
        return Err(StoiError::Invalid);
    }
    if overflowed {
        return Err(StoiError::OutOfRange);
    }

    let value = if negative { acc } else { -acc };
    if value < i64::from(i32::MIN) || value > i64::from(i32::MAX) {
        // Only reachable for +2147483648, which is in range for the negative
        // accumulator but not for a positive `int`.
        return Err(StoiError::OutOfRange);
    }
    Ok(value as i32)
}

/// Reproduces GCC's uncaught-exception death: the terminate message on stderr,
/// then `SIGABRT`.
///
/// The exact bytes, verified against the reference binary with `od -c` -- note
/// the two leading spaces on the second line and the *two* spaces after
/// `what():`, both easy to collapse to one:
///
/// ```text
/// terminate called after throwing an instance of 'std::invalid_argument'\n
/// ..what():..stoi\n
/// ```
///
/// # Why `process::abort` and not `exit(134)` or `panic!`
///
/// `std::terminate` calls `abort()`, so the process is *killed by a signal*. The
/// shell reports `134` for both `abort()` and `exit(134)`, but the raw wait
/// status differs (`0x0006` vs `0x8600`) and any harness using `WIFSIGNALED`
/// would spot the difference. `panic!` is doubly wrong: exit code 101 plus a
/// Rust backtrace note on stderr.
///
/// Aborting also discards whatever is sitting in Rust's line-buffered stdout,
/// which is the correct behaviour here: the C++ program writes nothing to stdout
/// before the throw, and verifying stdout is empty is part of the contract.
pub fn terminate_uncaught(error: StoiError) -> ! {
    let message = format!(
        "terminate called after throwing an instance of '{}'\n  what():  {}\n",
        error.cxx_type_name(),
        error.what()
    );

    // Errors are ignored deliberately: the C++ runtime aborts regardless of
    // whether the message reached a closed or full stderr.
    let mut stderr = std::io::stderr();
    let _ = stderr.write_all(message.as_bytes());
    let _ = stderr.flush();

    std::process::abort();
}

#[cfg(test)]
mod tests {
    use super::{c_stoi, c_stoi_bytes, StoiError};

    #[test]
    fn plain_decimal_values() {
        assert_eq!(c_stoi("0"), Ok(0));
        assert_eq!(c_stoi("1"), Ok(1));
        assert_eq!(c_stoi("50"), Ok(50));
        assert_eq!(c_stoi("150"), Ok(150));
        assert_eq!(c_stoi("200"), Ok(200));
        assert_eq!(c_stoi("201"), Ok(201));
        assert_eq!(c_stoi("-1"), Ok(-1));
        assert_eq!(c_stoi("-50"), Ok(-50));
    }

    #[test]
    fn optional_sign_but_never_two() {
        assert_eq!(c_stoi("+7"), Ok(7));
        assert_eq!(c_stoi("-7"), Ok(-7));
        assert_eq!(c_stoi("++7"), Err(StoiError::Invalid));
        assert_eq!(c_stoi("--3"), Err(StoiError::Invalid));
        assert_eq!(c_stoi("+-3"), Err(StoiError::Invalid));
        assert_eq!(c_stoi("-+3"), Err(StoiError::Invalid));
        assert_eq!(c_stoi("+"), Err(StoiError::Invalid));
        assert_eq!(c_stoi("-"), Err(StoiError::Invalid));
    }

    #[test]
    fn leading_c_locale_whitespace_is_skipped() {
        assert_eq!(c_stoi("  33  "), Ok(33));
        assert_eq!(c_stoi("\t\n\x0b\x0c\r 42"), Ok(42));
        assert_eq!(c_stoi("   +7"), Ok(7));
        // ...but no space may sit between the sign and the digits.
        assert_eq!(c_stoi("  +  7"), Err(StoiError::Invalid));
    }

    #[test]
    fn unicode_and_high_bytes_are_not_whitespace() {
        // strtol is C-locale: only the six ASCII space bytes count.
        assert_eq!(c_stoi_bytes(b"\xa042"), Err(StoiError::Invalid)); // Latin-1 NBSP
        assert_eq!(c_stoi_bytes(b"\xc2\xa042"), Err(StoiError::Invalid)); // UTF-8 NBSP
        assert_eq!(c_stoi_bytes(b"\xe2\x80\x8042"), Err(StoiError::Invalid)); // EN QUAD
        assert_eq!(c_stoi_bytes(b"\xef\xbb\xbf42"), Err(StoiError::Invalid)); // BOM
        assert_eq!(c_stoi_bytes(b"\x8542"), Err(StoiError::Invalid)); // NEL
    }

    #[test]
    fn non_ascii_digits_are_not_digits() {
        assert_eq!(c_stoi("\u{0663}"), Err(StoiError::Invalid)); // Arabic-Indic 3
        assert_eq!(c_stoi("\u{ff13}"), Err(StoiError::Invalid)); // fullwidth 3
    }

    #[test]
    fn parsing_stops_at_the_first_non_digit_without_erroring() {
        assert_eq!(c_stoi("12abc"), Ok(12));
        assert_eq!(c_stoi("3.9"), Ok(3));
        assert_eq!(c_stoi("2e3"), Ok(2));
        assert_eq!(c_stoi("1_000"), Ok(1));
        assert_eq!(c_stoi("1,000"), Ok(1));
        assert_eq!(c_stoi("1 2"), Ok(1));
        assert_eq!(c_stoi("7+"), Ok(7));
    }

    #[test]
    fn base_is_always_ten() {
        assert_eq!(c_stoi("0x10"), Ok(0));
        assert_eq!(c_stoi("0X10"), Ok(0));
        assert_eq!(c_stoi("0b101"), Ok(0));
        assert_eq!(c_stoi("010"), Ok(10));
        assert_eq!(c_stoi("0777"), Ok(777));
    }

    #[test]
    fn no_digits_at_all_is_invalid_argument() {
        assert_eq!(c_stoi(""), Err(StoiError::Invalid));
        assert_eq!(c_stoi("abc"), Err(StoiError::Invalid));
        assert_eq!(c_stoi(".5"), Err(StoiError::Invalid));
        assert_eq!(c_stoi("- 5"), Err(StoiError::Invalid));
        assert_eq!(c_stoi("inf"), Err(StoiError::Invalid));
        assert_eq!(c_stoi("nan"), Err(StoiError::Invalid));
        assert_eq!(c_stoi("   "), Err(StoiError::Invalid));
    }

    #[test]
    fn int_range_boundaries_are_inclusive() {
        assert_eq!(c_stoi("2147483647"), Ok(i32::MAX));
        assert_eq!(c_stoi("-2147483648"), Ok(i32::MIN));
        assert_eq!(c_stoi("2147483648"), Err(StoiError::OutOfRange));
        assert_eq!(c_stoi("-2147483649"), Err(StoiError::OutOfRange));
        assert_eq!(c_stoi("99999999999"), Err(StoiError::OutOfRange));
        assert_eq!(c_stoi("9223372036854775807"), Err(StoiError::OutOfRange));
        assert_eq!(c_stoi("9223372036854775808"), Err(StoiError::OutOfRange));
    }

    #[test]
    fn leading_zeros_do_not_count_toward_magnitude() {
        assert_eq!(c_stoi("0000002147483647"), Ok(i32::MAX));
        assert_eq!(c_stoi("0000002147483648"), Err(StoiError::OutOfRange));

        let mut zeros = "0".repeat(10_000);
        zeros.push_str("42");
        assert_eq!(c_stoi(&zeros), Ok(42));

        let mut signed_zeros = String::from("-");
        signed_zeros.push_str(&"0".repeat(10_000));
        signed_zeros.push_str("2147483648");
        assert_eq!(c_stoi(&signed_zeros), Ok(i32::MIN));
    }

    #[test]
    fn overflow_is_decided_over_the_whole_digit_run() {
        // The digits are consumed before the range check, so the trailing junk
        // cannot rescue an out-of-range prefix.
        assert_eq!(c_stoi("2147483648abc"), Err(StoiError::OutOfRange));
        assert_eq!(c_stoi("2147483647abc"), Ok(i32::MAX));
    }

    #[test]
    fn absurdly_long_digit_runs_do_not_overflow_the_accumulator() {
        assert_eq!(c_stoi(&"9".repeat(10_000)), Err(StoiError::OutOfRange));
        let mut one_then_zeros = String::from("1");
        one_then_zeros.push_str(&"0".repeat(100_000));
        assert_eq!(c_stoi(&one_then_zeros), Err(StoiError::OutOfRange));
    }

    #[test]
    fn exception_type_names_and_what_payload() {
        assert_eq!(StoiError::Invalid.cxx_type_name(), "std::invalid_argument");
        assert_eq!(StoiError::OutOfRange.cxx_type_name(), "std::out_of_range");
        // Both failure kinds share the same what() string.
        assert_eq!(StoiError::Invalid.what(), "stoi");
        assert_eq!(StoiError::OutOfRange.what(), "stoi");
    }
}
